import itertools

def calculate_autocorrelation(seq):
    n = len(seq)
    c = []
    for k in range(1, n):
        ck = sum(seq[i] * seq[i+k] for i in range(n-k))
        c.append(ck)
    return c

def solve():
    n = 13
    # The problem says C_k for k=1..12.
    # C_1 is c[0], C_2 is c[1], ..., C_4 is c[3], C_5 is c[4].
    # Let's re-read: "c[4]=2, c[5]=-1"
    # Does it mean C_4=2 and C_5=-1? Or c[4]=2 and c[5]=-1 (using 0-based indexing for c)?
    # Usually, C_k refers to the autocorrelation at lag k.
    # If the problem says "c[4]=2, c[5]=-1", it might mean C_4=2 and C_5=-1.
    # Let's test both interpretations.

    # Interpretation 1: C_4 = 2, C_5 = -1
    for seq in itertools.product([-1, 1], repeat=n):
        if seq[8] != 1 or seq[10] != -1:
            continue

        c = calculate_autocorrelation(seq)

        # C_k is c[k-1]
        if c[3] == 2 and c[4] == -1:
            sum_sq = sum(x**2 for x in c)
            if sum_sq <= 28:
                return list(seq)

    # Interpretation 2: c[4] = 2, c[5] = -1 (using 0-based indexing for the list c)
    # This would mean C_5 = 2, C_6 = -1
    for seq in itertools.product([-1, 1], repeat=n):
        if seq[8] != 1 or seq[10] != -1:
            continue

        c = calculate_autocorrelation(seq)

        if c[4] == 2 and c[5] == -1:
            sum_sq = sum(x**2 for x in c)
            if sum_sq <= 28:
                return list(seq)
    return None

result = solve()
print(result)
